/* Family profiles, nutrition plans, reminders and exercise selection. */
let familyProfiles=[{id:'default',name:'ملفي الشخصي'}],featureKind='',reportObjectURL=null;
const featureDialog=document.createElement('dialog');featureDialog.id='featureDialog';featureDialog.setAttribute('aria-labelledby','featureTitle');featureDialog.innerHTML='<form id="featureForm"><div class="dialog-head"><h2 id="featureTitle"></h2><button type="button" class="icon-button" data-feature="close">×</button></div><div id="featureFields" class="form-grid"></div><p id="featureError" role="alert" class="danger"></p><div class="dialog-actions"><button class="button" type="submit">حفظ ومتابعة</button><button class="button secondary" type="button" data-feature="close">إلغاء</button></div></form>';document.body.append(featureDialog);
const fb=(label,action,extra='')=>`<button type="button" class="button secondary" data-feature="${action}" ${extra}>${label}</button>`;
const checks=(name,label,checked=false)=>`<label class="check-label"><input type="checkbox" name="${name}" ${checked?'checked':''}> ${label}</label>`;
const profileName=()=>familyProfiles.find(x=>x.id===activeProfile)?.name||'ملف العائلة';
window.refreshFamilyBar=()=>{$('#familyBar').innerHTML=`<label for="familySelect">الملف الحالي</label><select id="familySelect">${familyProfiles.map(p=>`<option value="${esc(p.id)}" ${p.id===activeProfile?'selected':''}>${esc(p.name)}</option>`).join('')}</select>${fb('+ فرد جديد','profile')}<span class="sub">سجل وخطة مستقلان لكل فرد</span>`;const label=$('.sidebar-bottom div');if(label)label.innerHTML=esc(profileName())+'<small>ملف مستقل داخل حسابك</small>'};
async function profileAPI(method='GET',body){const r=await fetch('/api/profiles',{method,credentials:'same-origin',headers:body?{'content-type':'application/json'}:{},body:body?JSON.stringify(body):undefined});if(!r.ok)throw Error('تعذر الوصول لملفات العائلة. تحقق من الاتصال وتسجيل الدخول.');return r.json()}
async function loadProfiles(){try{familyProfiles=(await profileAPI()).profiles;if(!familyProfiles.some(p=>p.id===activeProfile)){localStorage.setItem('fitness-active-profile','default');location.reload();return}window.refreshFamilyBar();render()}catch(e){notify(e.message,true)}}
function switchProfile(id){if(syncBusy){notify('انتظر انتهاء المزامنة ثم بدّل الملف.');return}localStorage.setItem('fitness-active-profile',id);location.reload()}
document.addEventListener('change',e=>{if(e.target.id==='familySelect')switchProfile(e.target.value)});
window.familySettings=()=>`<div class="settings-grid feature-section"><div class="card"><div class="card-head"><h2>أفراد العائلة</h2>${fb('+ ملف جديد','profile')}</div><p class="sub">ملفات منفصلة تديرها من حسابك الحالي. هذه ليست حسابات دخول أو دعوات لأشخاص آخرين.</p>${familyProfiles.map(p=>`<div class="goal-row"><span>${esc(p.name)}</span>${p.id===activeProfile?'<span class="chip">الملف الحالي</span>':fb('فتح','switch',`data-id="${esc(p.id)}"`)}</div>`).join('')}</div><div class="card"><div class="card-head"><h2>تذكيرات المياه والوجبات</h2>${fb('ضبط المواعيد','reminders')}</div><p class="sub">تذكيرات الملف الحالي: ${data.reminders.enabled?'مفعّلة أثناء فتح التطبيق':'غير مفعّلة'}</p><div class="quick-buttons">${fb('تجربة التنبيه','test-reminder')}${fb('نقل المواعيد للتقويم','calendar')}</div><p class="notice">داخل التطبيق يظهر تنبيه عند الموعد أثناء بقائه مفتوحًا. للتنبيه وهو مغلق، أضف ملف المواعيد إلى تقويم الهاتف وفعّل إشعارات التقويم. لم يتم تفعيل Web Push.</p></div></div>`;
function openFeature(kind){featureKind=kind;$('#featureError').textContent='';let html='',title='';if(kind==='profile'){title='إضافة فرد للعائلة';html=input('name','اسم الفرد','','text',true,'maxlength="60"')+'<p class="form-note">يمكن إنشاء ملفات للأطفال لتسجيل الوجبات والنشاط. مولّد التنشيف والتضخيم مخصص للبالغين الأصحاء فقط.</p>'}if(kind==='reminders'){title='مواعيد التذكير';const r=data.reminders;html=checks('enabled','تفعيل تذكيرات هذا الملف',r.enabled)+input('start','أول تذكير مياه',r.start||'08:00','time',true)+input('end','آخر تذكير مياه',r.end||'21:00','time',true)+number('interval','تذكير مياه كل (دقيقة)',r.interval||90,true,30,1,360)+input('breakfast','الفطور',r.breakfast||'07:00','time',true)+input('snack','وجبة خفيفة',r.snack||'11:00','time',true)+input('lunch','الغداء',r.lunch||'14:00','time',true)+input('dinner','العشاء',r.dinner||'20:00','time',true)+'<p class="form-note">الأوقات حسب التوقيت المحلي للجهاز. لا نحدد كمية مياه علاجية؛ راعِ أي تعليمات طبية تخص السوائل.</p>'}if(kind==='intake'){title='InBody وخطة التغذية';const n=data.nutrition.intake||{},m=[...data.measurements].sort((a,b)=>b.date.localeCompare(a.date)).at(-1)||{};html='<label class="field full">صورة InBody للمراجعة (اختياري)<input id="reportImage" type="file" accept="image/*"></label><div id="reportPreview" class="field full"></div><p class="form-note">الصورة تُعرض على هذا الجهاز فقط ولا تُقرأ آليًا. انقل الأرقام إلى الحقول التالية، أو أرسل التقرير في المحادثة لأساعدك في قراءته.</p>'+input('date','تاريخ قياس InBody',n.date||m.date||selected,'date',true)+number('age','العمر (سنة)',n.age||'',true,1,1,100)+select('sex','الجنس',['ذكر','أنثى'],n.sex||'ذكر')+number('height','الطول (سم)',n.height||'',true,100,.1,230)+number('weight','الوزن (كجم)',n.weight||m.weight||'',true,25,.1,250)+number('bfr','دهون الجسم % (اختياري)',n.bfr??m.bfr,false,2,.1,70)+number('muscleWeight','كتلة العضلات كجم (اختياري)',n.muscleWeight??m.muscleWeight,false,1,.1,150)+number('bmr','BMR من التقرير (اختياري)',n.bmr??m.bmr,false,700,1,3500)+select('goal','الهدف',['تنشيف','تضخيم','ثبات الوزن'],n.goal||'تنشيف')+select('activity','مستوى النشاط',['قليل الحركة','نشاط خفيف','نشاط متوسط','نشاط مرتفع'],n.activity||'نشاط متوسط')+'<p class="sets-title">الحساسيات والاستبعادات</p>'+[['dairy','حليب ومشتقاته'],['egg','بيض'],['fish','سمك'],['nuts','مكسرات'],['gluten','جلوتين / قمح'],['soy','صويا']].map(([key,label])=>checks('exclude_'+key,label,(n.excluded||[]).includes(key))).join('')+input('otherAllergy','حساسيات أخرى (إن وجدت)',n.otherAllergy||'')+checks('medical','مرض مزمن، أدوية تؤثر على الغذاء، حمل/رضاعة أو تاريخ اضطراب أكل',n.medical)+'<p class="form-note">الخطة تقديرية للبالغين الأصحاء. لا تُنشأ خطط تنشيف أو تضخيم آلية للقُصّر أو للحالات الطبية الخاصة. الاستبعاد لا يضمن غياب آثار مسببات الحساسية؛ راجع ملصقات المنتجات.</p>'}$('#featureTitle').textContent=title;$('#featureFields').innerHTML=html;featureDialog.showModal()}
document.addEventListener('change',e=>{if(e.target.id==='reportImage'){if(reportObjectURL)URL.revokeObjectURL(reportObjectURL);const f=e.target.files[0];if(!f)return;if(f.size>15000000){$('#featureError').textContent='اختر صورة أقل من ١٥ ميجابايت.';return}reportObjectURL=URL.createObjectURL(f);$('#reportPreview').innerHTML=`<img src="${reportObjectURL}" alt="تقرير InBody للمراجعة" style="max-width:100%;max-height:420px;object-fit:contain">`}});
// Rounded food composition estimates per 100g; cooked weights unless stated.
const foods={egg:['بيض مسلوق',155,12.6,1.1,10.6,['egg']],bread:['خبز حبوب كاملة',247,13,41,4.2,['gluten']],rice:['أرز مطبوخ',130,2.7,28.2,.3,[]],oats:['شوفان جاف',379,13.2,67.7,6.5,['gluten']],yogurt:['زبادي يوناني قليل الدسم',73,9.9,3.9,1.9,['dairy']],chicken:['صدر دجاج مطبوخ',165,31,0,3.6,[]],beef:['لحم بقري قليل الدهن مطبوخ',200,29,0,8,[]],fish:['سمك أبيض مطبوخ',128,26,0,2.7,['fish']],salmon:['سلمون مطبوخ',206,22,0,12.4,['fish']],lentils:['عدس مطبوخ',116,9,20.1,.4,[]],tofu:['توفو متماسك',144,17.3,2.8,8.7,['soy']],potato:['بطاطس مسلوقة',87,1.9,20.1,.1,[]],banana:['موز مقشر',89,1.1,22.8,.3,[]],apple:['تفاح',52,.3,13.8,.2,[]],almonds:['لوز غير مملح',579,21.2,21.6,49.9,['nuts']],olive:['زيت زيتون',884,0,0,100,[]],veg:['خيار وطماطم وجزر',28,1.1,5.5,.2,[]]};
const foodTotal=items=>items.reduce((a,x)=>{const f=foods[x.key],q=x.g/100;return {calories:a.calories+f[1]*q,protein:a.protein+f[2]*q,carbs:a.carbs+f[3]*q,fat:a.fat+f[4]*q}},{calories:0,protein:0,carbs:0,fat:0});
function buildPlan(n){if(n.age<18||n.age>65||n.medical||n.otherAllergy.trim())throw Error('تم حفظ البيانات. هذه الحالة تحتاج خطة فردية من أخصائي تغذية؛ لن ننشئ خطة تنشيف أو تضخيم آلية.');const bmi=n.weight/(n.height/100)**2;if(bmi<18.5||bmi>35)throw Error('تم حفظ القياسات. الوزن بالنسبة للطول يحتاج تقييمًا فرديًا قبل وضع خطة تنشيف أو تضخيم.');const base=n.bmr||10*n.weight+6.25*n.height-5*n.age+(n.sex==='ذكر'?5:-161);const activity={'قليل الحركة':1.2,'نشاط خفيف':1.375,'نشاط متوسط':1.55,'نشاط مرتفع':1.725}[n.activity];const maintenance=Math.round(base*activity),calories=Math.round(maintenance*(n.goal==='تنشيف'?.85:n.goal==='تضخيم'?1.08:1)/25)*25;const floor=n.sex==='ذكر'?1500:1200;if(calories<floor||calories>4000)throw Error('تم حفظ القياسات. الاحتياج المحسوب خارج النطاق الآلي؛ اطلب ضبط الخطة من أخصائي.');const protein=Math.round(n.weight*1.6),fat=Math.round(calories*.28/9),carbs=Math.round((calories-protein*4-fat*9)/4);const allowed=k=>!foods[k][5].some(t=>n.excluded.includes(t));const safe=(list)=>list.find(allowed);const days=[];for(let d=0;d<7;d++){const breakfast=safe(['egg','tofu','chicken']),grain=safe(d%2?['oats','rice']:['bread','rice']),snack=safe(['yogurt','lentils']),main=safe([['chicken','fish','beef','salmon','chicken','beef','fish'][d],'chicken']),dinner=safe([d%2?'lentils':'fish','chicken']);const meals=[{name:'فطور',time:'07:00',items:[{key:breakfast,g:100,min:50,max:180},{key:grain,g:80,min:30,max:160},{key:'veg',g:150,min:150,max:150}]},{name:'سناك',time:'11:00',items:[{key:snack,g:170,min:100,max:300},{key:'apple',g:150,min:100,max:200}]},{name:'غداء',time:'14:00',items:[{key:main,g:160,min:100,max:250},{key:'rice',g:180,min:80,max:350},{key:'veg',g:250,min:250,max:250},{key:'olive',g:10,min:5,max:25}]},{name:'سناك',time:'16:30',items:[{key:'banana',g:120,min:100,max:180},...(allowed('almonds')?[{key:'almonds',g:20,min:10,max:35}]:[{key:'potato',g:150,min:80,max:220}])]},{name:'عشاء',time:'20:00',items:[{key:dinner,g:180,min:100,max:300},{key:'potato',g:180,min:80,max:350},{key:'veg',g:200,min:200,max:200},{key:'olive',g:10,min:5,max:25}]}];const items=meals.flatMap(m=>m.items),score=()=>{const t=foodTotal(items);return ((t.calories-calories)/calories)**2*6+((t.protein-protein)/protein)**2*3+((t.fat-fat)/fat)**2+((t.carbs-carbs)/carbs)**2};for(let pass=0;pass<100;pass++){let improved=false;for(const x of items){const old=x.g,start=score();let best=start,bg=old;for(const delta of [-5,5]){x.g=Math.max(x.min,Math.min(x.max,old+delta));const s=score();if(s<best){best=s;bg=x.g}}x.g=bg;if(bg!==old)improved=true}if(!improved)break}const total=foodTotal(items);if(Math.abs(total.calories-calories)/calories>.12||Math.abs(total.protein-protein)/protein>.25)throw Error('تم حفظ البيانات. لم نتمكن من إعداد وجبات متوازنة ضمن استبعاداتك واحتياجك؛ يلزم تخصيص الخطة مع أخصائي.');days.push({date:shift(selected,d),meals:meals.map(m=>({...m,...foodTotal(m.items)})),...total})}return {created:today(),start:selected,goal:n.goal,bmr:Math.round(base),maintenance,targets:{calories,protein,carbs,fat},days,method:n.bmr?'BMR من التقرير × معامل النشاط':'معادلة Mifflin–St Jeor × معامل النشاط'}}
window.renderNutritionPlan=()=>{const n=data.nutrition,plan=n.plan;return `<div class="daily-banner"><div><h2>خطة مناسبة لهدفك</h2><p>أطعمة طبيعية، كميات بالغرام، و٧ أيام متنوعة.</p></div>${fb(n.intake?'تعديل InBody والهدف':'أدخل بيانات InBody','intake')}</div>${n.blockReason?`<p class="notice">${esc(n.blockReason)}</p>`:''}${!plan?empty('أدخل قياساتك وبياناتك لإنشاء مسودة غذائية. لا تُسجل الوجبات كمأكولة إلا عندما تختار ذلك.'): `<div class="card"><div class="card-head"><h2>${esc(plan.goal)} · ${esc(profileName())}</h2>${fb('اعتماد الأهداف الغذائية','apply-plan')}</div><div class="mini-grid"><div class="mini"><small>السعرات المستهدفة</small><strong>${fmt(plan.targets.calories)}</strong></div><div class="mini"><small>بروتين مستهدف</small><strong>${fmt(plan.targets.protein)} غ</strong></div><div class="mini"><small>سعرات الثبات التقديرية</small><strong>${fmt(plan.maintenance)}</strong></div></div><p class="sub">${esc(plan.method)}. التنشيف: خفض تقديري ١٥٪، والتضخيم: زيادة تقديرية ٨٪. هذه نقطة بدء قابلة للمراجعة وفق تقدمك.</p><p class="notice">جميع الأوزان بعد الطبخ أو للجزء المأكول، باستثناء الشوفان فهو جاف. القيم تقريبية وتتغير باختلاف المنتج والطهي. السعرات الفعلية لكل يوم أدناه قد تختلف قليلًا عن الهدف. راجع الخطة إذا تغير نشاطك أو وزنك.</p></div>${plan.days.map((day,di)=>`<div class="card"><div class="card-head"><h2>${pretty(day.date,{weekday:'long',day:'numeric',month:'long'})}</h2><span class="chip">${fmt(day.calories)} سعرة · بروتين ${fmt(day.protein)} غ</span></div><div class="plan-meals">${day.meals.map((m,mi)=>`<article class="record"><div class="record-head"><h3>${esc(m.name)} · ${m.time}</h3>${fb('تسجيل كوجبة مأكولة','log-plan',`data-day="${di}" data-meal="${mi}"`)}</div><p>${m.items.map(x=>`${foods[x.key][0]} <b>${x.g} غ</b>`).join(' + ')}</p><div class="chips"><span class="chip">${fmt(m.calories)} سعرة</span><span class="chip">P ${fmt(m.protein)} غ</span><span class="chip">C ${fmt(m.carbs)} غ</span><span class="chip">F ${fmt(m.fat)} غ</span></div></article>`).join('')}</div></div>`).join('')}`}<div class="card"><h3>كيف تُحسب الخطة؟</h3><p class="sub">من الوزن والطول والعمر والجنس والنشاط، مع استخدام BMR من التقرير إن أدخلته. بيانات الدهون والعضلات تُحفظ للمتابعة؛ لا تُستخدم لتشخيص حالة صحية. البروتين المستهدف ١٫٦ غ/كجم للبالغين الأصحاء النشطين.</p><div class="quick-buttons"><a class="text-button" href="https://pubmed.ncbi.nlm.nih.gov/2305711/" target="_blank" rel="noopener">معادلة الطاقة</a><a class="text-button" href="https://doi.org/10.1186/s12970-017-0177-8" target="_blank" rel="noopener">مرجع البروتين</a><a class="text-button" href="https://fdc.nal.usda.gov/" target="_blank" rel="noopener">قيم الأطعمة المرجعية</a></div></div>`};
$('#featureForm').addEventListener('submit',async e=>{e.preventDefault();if(!e.target.reportValidity())return;const f=Object.fromEntries(new FormData(e.target));$('#featureError').textContent='';try{if(featureKind==='profile'){const result=await profileAPI('POST',{name:f.name});familyProfiles.push(result);featureDialog.close();window.refreshFamilyBar();render();notify('تم إنشاء ملف '+result.name);return}const next=structuredClone(data);if(featureKind==='reminders'){if(f.start>=f.end)throw Error('نهاية التذكيرات يجب أن تكون بعد بدايتها في اليوم نفسه.');next.reminders={...f,enabled:f.enabled==='on',interval:num(f.interval)};if(commit(next,'تم حفظ التذكيرات'))featureDialog.close();return}if(featureKind==='intake'){const n={date:f.date,age:num(f.age),sex:f.sex,height:num(f.height),weight:num(f.weight),bmr:f.bmr?num(f.bmr):null,bfr:f.bfr?num(f.bfr):null,muscleWeight:f.muscleWeight?num(f.muscleWeight):null,goal:f.goal,activity:f.activity,excluded:['dairy','egg','fish','nuts','gluten','soy'].filter(k=>f['exclude_'+k]==='on'),medical:f.medical==='on',otherAllergy:f.otherAllergy.trim()};if(!dateValid(n.date))throw Error('تاريخ القياس غير صالح.');next.nutrition={intake:n,plan:null,blockReason:''};const existing=next.measurements.find(x=>x.date===n.date&&x.weight===n.weight);const measurement={...(existing||{}),id:existing?.id||uid(),date:n.date,weight:n.weight,bfr:n.bfr,muscleWeight:n.muscleWeight,bmr:n.bmr,bmi:Math.round(n.weight/(n.height/100)**2*10)/10};if(existing)Object.assign(existing,measurement);else next.measurements.push(measurement);try{next.nutrition.plan=buildPlan(n)}catch(err){next.nutrition.blockReason=err.message}if(commit(next,'تم حفظ بيانات التغذية')){featureDialog.close();location.hash='nutrition';view='nutrition';render()}}}catch(err){$('#featureError').textContent=err.message}});
const minute=t=>num(t.split(':')[0])*60+num(t.split(':')[1]);const clock=n=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;
function reminderTimes(r){if(!r.enabled)return [];const times=[];for(let t=minute(r.start);t<=minute(r.end);t+=r.interval)times.push({time:clock(t),kind:'water',title:'وقت شرب المياه'});for(const [k,title] of [['breakfast','وقت الفطور'],['snack','وقت الوجبة الخفيفة'],['lunch','وقت الغداء'],['dinner','وقت العشاء']])if(r[k])times.push({time:r[k],kind:k,title});return times.sort((a,b)=>a.time.localeCompare(b.time))}
function remind(){if(document.hidden||!data.reminders.enabled)return;const now=timeNow();for(const r of reminderTimes(data.reminders)){if(r.time!==now)continue;const key=KEY+'-reminder-'+today()+'-'+r.kind+'-'+now;if(localStorage.getItem(key))continue;localStorage.setItem(key,'1');notify(profileName()+': '+r.title);const banner=document.createElement('div');banner.className='reminder-banner';banner.setAttribute('role','alert');banner.innerHTML=`<strong>${esc(r.title)}</strong><span>${esc(profileName())}</span><button class="button secondary" data-feature="dismiss-reminder">حسنًا</button>`;document.body.append(banner)}}
function downloadCalendar(){const times=reminderTimes(data.reminders);if(!times.length){notify('فعّل التذكيرات واضبط المواعيد أولًا.',true);return}const escapeICS=s=>s.replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');const date=today().replaceAll('-',''),stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Fitness Tracker//Reminders//AR','CALSCALE:GREGORIAN'];for(const [i,r] of times.entries()){const start=date+'T'+r.time.replace(':','')+'00';lines.push('BEGIN:VEVENT','UID:'+activeProfile+'-'+r.kind+'-'+r.time.replace(':','')+'@fitness-tracker','DTSTAMP:'+stamp,'DTSTART:'+start,'DURATION:PT5M','RRULE:FREQ=DAILY;COUNT=90','SUMMARY:'+escapeICS(r.title+' — '+profileName()),'DESCRIPTION:'+escapeICS('تذكير من Fitness Tracker. لتغيير الجدول أو إيقافه عدّل أو احذف الأحداث المتكررة في تطبيق التقويم.'),'BEGIN:VALARM','ACTION:DISPLAY','TRIGGER:PT0S','DESCRIPTION:'+escapeICS(r.title),'END:VALARM','END:VEVENT')}lines.push('END:VCALENDAR');const url=URL.createObjectURL(new Blob([lines.map(line=>{let parts=[],chunk='';for(const ch of line){if(new TextEncoder().encode(chunk+ch).length>72){parts.push(chunk);chunk=' '+ch}else chunk+=ch}parts.push(chunk);return parts.join('\r\n')}).join('\r\n')+'\r\n'],{type:'text/calendar;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='Fitness-Reminders-'+today()+'.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('افتح ملف التقويم وأضف المواعيد. تغيير إعدادات التطبيق لا يعدّل أحداث التقويم المستوردة.')}
document.addEventListener('click',e=>{const el=e.target.closest('[data-feature]');if(!el)return;const a=el.dataset.feature;if(['profile','reminders','intake'].includes(a))openFeature(a);else if(a==='close')featureDialog.close();else if(a==='switch')switchProfile(el.dataset.id);else if(a==='test-reminder')notify(profileName()+': حان وقت شرب المياه — تنبيه تجريبي');else if(a==='dismiss-reminder')el.closest('.reminder-banner').remove();else if(a==='calendar')downloadCalendar();else if(a==='apply-plan'){if(!data.nutrition.plan)return;const next=structuredClone(data);Object.assign(next.targets,next.nutrition.plan.targets);commit(next,'تم اعتماد أهداف الخطة')}else if(a==='log-plan'){const day=data.nutrition.plan?.days[num(el.dataset.day)],m=day?.meals[num(el.dataset.meal)];if(!m)return;const currentDate=selected;openForm('meal',{...m,date:currentDate,food:m.items.map(x=>`${foods[x.key][0]} ${x.g} غ`).join(' + ')},true)}});
window.refreshFamilyBar();loadProfiles();render();setInterval(remind,20000);remind();
