const originalOpenForm=openForm;
openForm=function(kind,record=null,repeat=false){originalOpenForm(kind,record,repeat);if(kind!=='workout')return;const box=document.createElement('div');box.className='exercise-picker';box.innerHTML='<h3>مكتبة التمارين والأجهزة</h3><p class="sub">أجهزة شائعة تناسب التدريب في PureGym؛ توفر الجهاز يختلف حسب الفرع.</p><div class="form-grid">'+input('librarySearch','ابحث عربي أو English','','search')+select('libraryEquipment','نوع الجهاز / الأداة',['الكل','جهاز مقاومة','جهاز مساعدة','كابل','دامبل','بار','سميث','كيتلبيل','وزن الجسم','كارديو'],'الكل')+'<label class="field full">اختر التمرين<select id="exerciseChoice"><option value="">تمرين مخصص / اختر من المكتبة</option></select></label></div>';$('#fields').prepend(box);box.querySelector('[name=librarySearch]').removeAttribute('name');box.querySelector('[name=libraryEquipment]').removeAttribute('name');const filters=()=>{const query=box.querySelector('input').value.toLowerCase(),equipment=box.querySelector('select').value;$('#exerciseChoice').innerHTML='<option value="">تمرين مخصص / اختر من المكتبة</option>'+exerciseLibrary.map((x,i)=>({x,i})).filter(({x})=>(equipment==='الكل'||x[3]===equipment)&&x.join(' ').toLowerCase().includes(query)).map(({x,i})=>`<option value="${i}">${esc(x[0]+' · '+x[2]+' — '+x[1])}</option>`).join('')};box.querySelector('input').addEventListener('input',filters);box.querySelector('select').addEventListener('change',filters);const extras=document.createElement('div');extras.className='field full';extras.innerHTML='<div class="form-grid">'+input('equipment','اسم الجهاز / الأداة',record?.equipment||'')+select('exerciseType','نوع التدريب',['مقاومة','كارديو'],record?.exerciseType||'مقاومة')+number('distance','مسافة الكارديو كم (اختياري)',record?.distance||'',false,0,.01,500)+'</div><p class="form-note">في الدامبل سجّل وزن دامبل واحد وثبّت نفس الطريقة للمقارنة. في وزن الجسم سجّل الحمل الإضافي فقط (صفر إن لم يوجد). في جهاز المساعدة سجّل مقدار المساعدة.</p>';$('#fields').append(extras);const type=$('#fields select[name=exerciseType]');const setType=()=>{const cardio=type.value==='كارديو';for(let i=1;i<=4;i++)for(const k of ['w','r']){const el=$('#fields input[name='+k+i+']');el.disabled=cardio;el.required=!cardio&&i<=3;el.closest('label').hidden=cardio}$('#fields').querySelectorAll('.sets-title').forEach(x=>x.hidden=cardio);const dur=$('#fields input[name=duration]');dur.required=cardio;$('#fields input[name=distance]').closest('label').hidden=!cardio};type.addEventListener('change',setType);$('#exerciseChoice').addEventListener('change',e=>{if(e.target.value==='')return;const x=exerciseLibrary[num(e.target.value)];$('#fields input[name=exercise]').value=x[1]+' — '+x[2];const group=$('#fields select[name=group]');if(![...group.options].some(o=>o.value===x[0]))group.add(new Option(x[0],x[0]));group.value=x[0];$('#fields input[name=equipment]').value=x[3];type.value=x[3]==='كارديو'?'كارديو':'مقاومة';setType()});filters();setType()};
